B.ah3=new A.b2("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.c5=new A.lV("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.a2v=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.aUc=new A.aa(B.c5,B.a2v,!1)
B.be=new A.lV("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.a5S=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.aW8=new A.aa(B.be,B.a5S,!1)
B.aa2=s([B.ah3,B.aUc,B.aW8],t.a)
B.aX8=new A.cy("story_00_intro",B.aa2)
B.agx=new A.b2("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.a3c=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.aUk=new A.aa(B.c5,B.a3c,!1)
B.aha=new A.b2("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.a3l=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.aUg=new A.aa(B.be,B.a3l,!1)
B.cb=new A.lV("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.ab0=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.aVY=new A.aa(B.cb,B.ab0,!1)
B.a3x=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.aVp=new A.aa(B.c5,B.a3x,!1)
B.aac=s([B.agx,B.aUk,B.aha,B.aUg,B.aVY,B.aVp],t.a)
B.aWR=new A.cy("story_01a_clubhouse_arrival",B.aac)
B.a4C=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.aUP=new A.aa(B.c5,B.a4C,!1)
B.a6c=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.aVt=new A.aa(B.cb,B.a6c,!1)
B.a1A=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.aVL=new A.aa(B.be,B.a1A,!1)
B.a3h=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.aVI=new A.aa(B.cb,B.a3h,!1)
B.a2x=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.aV1=new A.aa(B.be,B.a2x,!1)
B.a0y=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.aU_=new A.aa(B.c5,B.a0y,!1)
B.a8i=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.aWc=new A.aa(B.be,B.a8i,!1)
B.acb=s([B.aUP,B.aVt,B.aVL,B.aVI,B.aV1,B.aU_,B.aWc],t.a)
B.aWM=new A.cy("story_01b_legend_and_time",B.acb)
B.ahB=new A.b2("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.a4G=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.aUW=new A.aa(B.be,B.a4G,!1)
B.a44=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.aWl=new A.aa(B.cb,B.a44,!1)
B.abG=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.aVH=new A.aa(B.be,B.abG,!1)
B.a7V=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.aTV=new A.aa(B.cb,B.a7V,!1)
B.a2j=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.aTY=new A.aa(B.c5,B.a2j,!1)
B.a6H=s([B.ahB,B.aUW,B.aWl,B.aVH,B.aTV,B.aTY],t.a)
B.aWL=new A.cy("story_02_torn_map",B.a6H)
B.a1B=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.aUV=new A.aa(B.c5,B.a1B,!1)
B.a8J=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.aW2=new A.aa(B.be,B.a8J,!1)
B.agR=new A.b2("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.ab4=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.aW3=new A.aa(B.cb,B.ab4,!1)
B.abj=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.aW6=new A.aa(B.be,B.abj,!1)
B.a7s=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.aUi=new A.aa(B.c5,B.a7s,!1)
B.a1X=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.aUN=new A.aa(B.be,B.a1X,!1)
B.a21=s([B.aUV,B.aW2,B.agR,B.aW3,B.aW6,B.aUi,B.aUN],t.a)
B.aWN=new A.cy("story_03_founders_trail",B.a21)
B.agz=new A.b2("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.a3J=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.aWg=new A.aa(B.be,B.a3J,!1)
B.a8d=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.aVC=new A.aa(B.cb,B.a8d,!1)
B.aaL=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.aVM=new A.aa(B.be,B.aaL,!1)
B.a4X=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.aVu=new A.aa(B.c5,B.a4X,!1)
B.a19=s([B.agz,B.aWg,B.aVC,B.aVM,B.aVu],t.a)
B.aWJ=new A.cy("story_04_flowers_in_mud",B.a19)
B.agW=new A.b2("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.a2W=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.aUr=new A.aa(B.be,B.a2W,!1)
B.a0D=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.aVo=new A.aa(B.cb,B.a0D,!1)
B.a5s=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.aWp=new A.aa(B.be,B.a5s,!1)
B.ack=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.aUM=new A.aa(B.c5,B.ack,!1)
B.a7P=s([B.agW,B.aUr,B.aVo,B.aWp,B.aUM],t.a)
B.aXi=new A.cy("story_05_old_oak",B.a7P)
B.agS=new A.b2("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.a8O=s(["\u201eCo se to stalo?\u201c"],t.s)
B.aW7=new A.aa(B.be,B.a8O,!1)
B.a5i=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.aUK=new A.aa(B.c5,B.a5i,!1)
B.a33=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.aUI=new A.aa(B.be,B.a33,!1)
B.a5U=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.aVx=new A.aa(B.c5,B.a5U,!1)
B.agE=new A.b2("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.a5v=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.aVl=new A.aa(B.cb,B.a5v,!1)
B.ac1=s([B.agS,B.aW7,B.aUK,B.aUI,B.aVx,B.agE,B.aVl],t.a)
B.aWO=new A.cy("story_06_waterfall_chest",B.ac1)
B.ah9=new A.b2("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.a47=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.aWr=new A.aa(B.cb,B.a47,!1)
B.abY=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.aUL=new A.aa(B.c5,B.abY,!1)
B.ahs=new A.b2("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.ac9=s([B.ah9,B.aWr,B.aUL,B.ahs],t.a)
B.aX3=new A.cy("story_07_scroll",B.ac9)
B.agp=new A.b2("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aaA=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.aWh=new A.aa(B.be,B.aaA,!1)
B.a9j=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.aTN=new A.aa(B.cb,B.a9j,!1)
B.a3e=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.aTS=new A.aa(B.be,B.a3e,!1)
B.a6t=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.aUs=new A.aa(B.cb,B.a6t,!1)
B.a7h=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.aW4=new A.aa(B.c5,B.a7h,!1)
B.a7Q=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.aTK=new A.aa(B.cb,B.a7Q,!1)
B.a7L=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.aUu=new A.aa(B.be,B.a7L,!1)
B.a5t=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.aVb=new A.aa(B.cb,B.a5t,!1)
B.a2u=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.aUf=new A.aa(B.c5,B.a2u,!1)
B.a2b=s([B.agp,B.aWh,B.aTN,B.aTS,B.aUs,B.aW4,B.aTK,B.aUu,B.aVb,B.aUf],t.a)
B.aWU=new A.cy("story_08_ending_dialogue",B.a2b)
